package com.bobbuy.api;
import static com.bobbuy.test.RecommendationPublicationFixtures.*;
import com.bobbuy.model.*;import com.bobbuy.repository.*;import com.bobbuy.service.*;import com.bobbuy.security.JwtTokenService;import com.fasterxml.jackson.databind.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.annotation.DirtiesContext;import org.springframework.test.web.servlet.*;
import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:marker_integration;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","bobbuy.security.header-auth.enabled=false"})
@AutoConfigureMockMvc(print=org.springframework.boot.test.autoconfigure.web.servlet.MockMvcPrint.NONE) @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class ProductMarkerIntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired BobbuyStore store;@Autowired UserRepository users;@Autowired ProductRepository products;@Autowired RecommendationPostRepository posts;@Autowired RecommendationItemRepository items;@Autowired ProductMarkerDefinitionRepository definitions;@Autowired ProductMarkerSetRepository sets;@Autowired JwtTokenService tokens;
 String agent,foreign,customer;String productId="marker-reference";
 @BeforeEach void setup(){sets.deleteAll();definitions.deleteAll();items.deleteAll();posts.deleteAll();store.seed();var other=new User(9090L,"Other synthetic merchant",Role.AGENT,0);users.saveAndFlush(other);agent=tokens.createAccessToken(users.findById(1000L).orElseThrow());foreign=tokens.createAccessToken(other);customer=tokens.createAccessToken(users.findById(1001L).orElseThrow());
  var p=new Product();p.setId(productId);p.setMerchantId(1000L);p.setName(Map.of("ja-JP","Private master name"));p.setBrand("PRIVATE_BRAND");p.setVisibilityStatus(ProductVisibility.DRAFTER_ONLY);products.saveAndFlush(p);var post=new RecommendationPost();post.merchantId=1000L;post.title="Synthetic source";legacyPost(post);posts.saveAndFlush(post);var item=new RecommendationItem();item.productId=productId;item.postId=post.id;item.name="Already public source";item.itemNumber="QA-MARKER";item.imageHash="a".repeat(64);item.imageUrl="https://example.invalid/private-raw";item.gallery=List.of(new RecommendationItem.Picture("i","https://example.invalid/public.jpg",null,null,null,null,null));legacyItem(item,post);items.saveAndFlush(item);
 }
 JsonNode data(ResultActions r)throws Exception{return json.readTree(r.andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).get("data");}
 String route(){return "/api/merchant/product-markers";}
 Map<String,Object> input(String code,String badge,int order){return new LinkedHashMap<>(Map.of("code",code,"badge",badge,"name",Map.of("ja-JP","表示","zh-CN","显示","zh-TW","顯示","en-US","Display"),"description",Map.of(),"color","red","sortOrder",order,"enabled",true));}
 JsonNode create(String code,int order)throws Exception{return data(mvc.perform(post(route()).header("Authorization","Bearer "+agent).contentType("application/json").content(json.writeValueAsString(input(code,"新",order)))));}
 JsonNode assign(List<String> ids,long version)throws Exception{return data(mvc.perform(put(route()+"/products/"+productId).header("Authorization","Bearer "+agent).contentType("application/json").content(json.writeValueAsString(Map.of("markerIds",ids,"version",version)))));}
 @Test void anonymousCustomerAndForeignOwnerCannotMutateOrReadMerchantAssignments()throws Exception{
  mvc.perform(get(route())).andExpect(status().isUnauthorized());mvc.perform(get(route()).header("Authorization","Bearer "+customer)).andExpect(status().isForbidden());mvc.perform(get(route()+"/products/"+productId).header("Authorization","Bearer "+foreign)).andExpect(status().isNotFound());mvc.perform(put(route()+"/products/"+productId).header("Authorization","Bearer "+foreign).contentType("application/json").content("{\"markerIds\":[],\"version\":0}")).andExpect(status().isNotFound());mvc.perform(post("/api/storefront/product-marker-assignments")).andExpect(status().isUnauthorized());
 }
 @Test void defaultsAreExplicitIdempotentAndNeverAssignProducts()throws Exception{var a=data(mvc.perform(post(route()+"/defaults").header("Authorization","Bearer "+agent)));var b=data(mvc.perform(post(route()+"/defaults").header("Authorization","Bearer "+agent)));assertThat(a).hasSize(4);assertThat(b).isEqualTo(a);assertThat(a.findValuesAsText("badge")).containsExactly("新","折","少","缺");assertThat(sets.count()).isZero();assertThat(data(mvc.perform(get("/api/storefront/marked-product-catalog"))).path("total").asLong()).isZero();}
 @Test void realPersistenceVersionRetryClearAndNegativeVersion()throws Exception{var a=create("first",20);var b=create("second",0);String aid=a.path("id").asText(),bid=b.path("id").asText();var saved=assign(List.of(aid,bid),0);assertThat(saved.path("version").asLong()).isEqualTo(1);assertThat(saved.path("markerIds").get(0).asText()).isEqualTo(bid);var reload=data(mvc.perform(get(route()+"/products/"+productId).header("Authorization","Bearer "+agent)));assertThat(reload).isEqualTo(saved);assertThat(assign(List.of(bid,aid),0)).isEqualTo(saved);mvc.perform(put(route()+"/products/"+productId).header("Authorization","Bearer "+agent).contentType("application/json").content("{\"markerIds\":[],\"version\":0}")).andExpect(status().isBadRequest());assertThat(assign(List.of(),1).path("version").asLong()).isEqualTo(2);mvc.perform(put(route()+"/products/"+productId).header("Authorization","Bearer "+agent).contentType("application/json").content("{\"markerIds\":[],\"version\":-1}")).andExpect(status().isBadRequest());}
 @Test void referenceOnlyMarkersReuseExactlyPublicCatalogAndDisappearOnWithdrawal()throws Exception{var marker=create("new",0);assign(List.of(marker.path("id").asText()),0);var marked=data(mvc.perform(get("/api/storefront/marked-product-catalog")));assertThat(marked.path("total").asLong()).isEqualTo(1);var row=marked.path("items").get(0);assertThat(row.path("name").path("ja-JP").asText()).isEqualTo("Already public source");assertThat(row.path("brand").isNull()).isTrue();assertThat(row.toString()).doesNotContain("PRIVATE_BRAND","Private master name","private-raw");var post=posts.findByPublishedTrue().get(0);post.published=false;posts.saveAndFlush(post);assertThat(data(mvc.perform(get("/api/storefront/marked-product-catalog"))).path("total").asLong()).isZero();assertThat(data(mvc.perform(get("/api/storefront/product-marker-assignments").param("productIds",productId)))).isEmpty();assertThat(sets.count()).isEqualTo(1);}
 @Test void disableAndReenableDefinitionRetainsAssignmentAndDoesNotChangeProductPrice()throws Exception{var marker=create("status",0);String id=marker.path("id").asText();assign(List.of(id),0);var body=input("status","缺",0);body.put("version",0);body.put("enabled",false);var disabled=data(mvc.perform(put(route()+"/"+id).header("Authorization","Bearer "+agent).contentType("application/json").content(json.writeValueAsString(body))));assertThat(disabled.path("version").asLong()).isEqualTo(1);assertThat(data(mvc.perform(get("/api/storefront/marked-product-catalog"))).path("total").asLong()).isZero();assertThat(sets.findById(productId).orElseThrow().markerIds).containsExactly(id);body.put("version",1);body.put("enabled",true);data(mvc.perform(put(route()+"/"+id).header("Authorization","Bearer "+agent).contentType("application/json").content(json.writeValueAsString(body))));assertThat(data(mvc.perform(get("/api/storefront/marked-product-catalog"))).path("total").asLong()).isEqualTo(1);assertThat(products.findById(productId).orElseThrow().getVisibilityStatus()).isEqualTo(ProductVisibility.DRAFTER_ONLY);assertThat(products.findById(productId).orElseThrow().getBasePrice()).isZero();}
 @Test void malformedAndOversizedPublicQueriesFail400()throws Exception{for(String page:List.of("-1","100001","abc"))mvc.perform(get("/api/storefront/marked-product-catalog").param("page",page)).andExpect(status().isBadRequest());mvc.perform(get("/api/storefront/product-marker-assignments").param("productIds","a,a")).andExpect(status().isBadRequest());mvc.perform(get("/api/storefront/marked-product-catalog").param("merchantId","0")).andExpect(status().isBadRequest());}
 @Test void foreignDefinitionCannotBeAttachedToOwnReferenceProduct()throws Exception{var d=data(mvc.perform(post(route()).header("Authorization","Bearer "+foreign).contentType("application/json").content(json.writeValueAsString(input("foreign","新",0)))));mvc.perform(put(route()+"/products/"+productId).header("Authorization","Bearer "+agent).contentType("application/json").content(json.writeValueAsString(Map.of("markerIds",List.of(d.path("id").asText()),"version",0)))).andExpect(status().isBadRequest());assertThat(sets.count()).isZero();mvc.perform(put(route()+"/"+d.path("id").asText()).header("Authorization","Bearer "+agent).contentType("application/json").content(json.writeValueAsString(input("foreign","新",0)))).andExpect(status().isNotFound());}
}
